content:
{
  "is_open_solicitation": true,
  "buyer": "Town of Yarmouth, Massachusetts",
  "title": "Consultant Planning, Landscape Architecture, Engineering, and Design Services for the Creation of a Town Common at Simpkins Field",
  "due_date": "2026-10-01",
  "fit_score": 0,
  "why_fit": [],
  "gaps": [
    "Requires licensed landscape architecture and civil/site engineering services for physical public space design",
    "Demands site assessment of utilities, topography, jurisdictional constraints, and traffic/pedestrian circulation",
    "Requires construction cost estimation for phased building, materials, and operation/maintenance",
    "Seeks conceptual design alternatives with climate-resilient landscaping, permeable pavers, and lighting",
    "Needs community engagement for physical civic space planning, not digital services",
    "Requires professional licensure and insurance/bonding for construction consulting",
    "Company only provides website redesign, mobile app development, and hosting/maintenance",
    "Company explicitly cannot do construction, hardware supply, or on-site staff augmentation"
  ],
  "requirements": [
    "Separate Technical Proposal and Price Proposal in separately sealed envelopes",
    "Submission to Town Administrator's Office, 1146 Route 28, South Yarmouth, MA 02664 by 3:00 PM October 1, 2026",
    "Technical Proposal describing means, methods, approach, and deliverables",
    "Price Proposal on provided Price Proposal Worksheet",
    "Certificates of Insurance meeting contract requirements before execution",
    "Compliance with M.G.L. Chapter 30B Uniform Procurement Act",
    "Demonstrated experience in community planning, landscape architecture, urban design, public engagement",
    "Past performance references for similar public space projects",
    "Staffing qualifications for planning, landscape architecture, engineering",
    "Community engagement approach with minimum three public meetings",
    "Project management and ability to meet 9-month schedule"
  ],
  "evidence": [
    {
      "claim": "RFP seeks planning, landscape architecture, engineering, and design for physical town common",
      "quote": "planning, landscape architecture, engineering, and design consulting services for the feasibility study, conceptual design, and cost estimation"
    },
    {
      "claim": "Scope includes site assessment of utilities, topography, and traffic circulation",
      "quote": "identify pavements, utilities, structures, resource delineations, jurisdictional constraints, and topography. Analyze circulation and traffic around the property"
    },
    {
      "claim": "Requires conceptual design alternatives with landscaping, pavers, lighting for physical space",
      "quote": "develop and present three (3) conceptual design alternatives. Include recommendations for materials, durable and climate-resilient landscaping, permeable pavers, and lighting"
    },
    {
      "claim": "Cost estimation covers construction, materials, bidding assistance, and operation/maintenance",
      "quote": "Prepare planning-level cost estimates for phased construction and future operation and maintenance. Cost estimates shall include final design, bidding assistance, materials, and construction"
    },
    {
      "claim": "Proposals due October 1, 2026 at 3:00 PM in sealed envelopes to Town Hall",
      "quote": "Proposals must be received by the Town Administrator's Office, Yarmouth Town Hall, 1146 Route 28, South Yarmouth, MA 02664, no later than 3:00 p.m. on October 1, 2026"
    },
    {
      "claim": "Separate Technical and Price Proposals required in sealed envelopes",
      "quote": "A response to this RFP must consist of a separate Technical Proposal and a separate Price Proposal, each submitted in a separately sealed envelope"
    },
    {
      "claim": "Insurance certificates required before contract execution",
      "quote": "The selected proposer shall submit Certificates of Insurance meeting the requirements of the Contract before execution"
    },
    {
      "claim": "Evaluation criteria emphasize landscape architecture, urban design, public engagement experience",
      "quote": "demonstrated experience in community planning, landscape architecture, urban design, public engagement, conceptual site design, and cost estimating for public spaces"
    }
  ]
}
